  'files/lefthook.yml':
    "pre-commit:\n  jobs:\n    - name: gitleaks\n      priority: 0\n      run: mise install -q && mise exec -- gitleaks git --staged --redact --no-banner\n    - name: protect-main\n      priority: 0\n      run: test \"$(git branch --show-current)\" != \"main\"\n      fail_text: main is protected. Create a branch (one job = one worktree/branch + PR)\n    - name: lint\n      priority: 1\n      glob: '*.{ts,tsx,mts,js,jsx,mjs,cjs}'\n      run: ./node_modules/.bin/oxlint --fix --deny-warnings --no-error-on-unmatched-pattern {staged_files}\n      stage_fixed: true\n    - name: dup\n      priority: 1\n      glob: '*.{ts,tsx,mts}'\n      run: ./node_modules/.bin/jscpd -c .jscpd.json {staged_files}\n    - name: spell\n      priority: 1\n      run: ./node_modules/.bin/cspell --no-progress --no-must-find-files {staged_files}\n    - name: dead\n      priority: 1\n      glob: '*.{ts,tsx,mts}'\n      run: ./node_modules/.bin/knip\n    - name: boundaries\n      priority: 1\n      glob: 'src/**/*.ts'\n      run: ./node_modules/.bin/depcruise src --config .dependency-cruiser.cjs\n    - name: fmt\n      priority: 2\n      glob: '*.{ts,tsx,mts,js,jsx,mjs,cjs,json,md,yaml,yml}'\n      run: ./node_modules/.bin/oxfmt --no-error-on-unmatched-pattern {staged_files}\n      stage_fixed: true\n    - name: workflows\n      glob: '.github/workflows/*'\n      run: bun run lint:workflows\n    - name: typecheck\n      priority: 3\n      run: ./node_modules/.bin/tsc --noEmit -p tsconfig.json\n\ncommit-msg:\n  jobs:\n    - name: commitlint\n      run: ./node_modules/.bin/commitlint --edit {1}\n",
