  'files/source/commands/hello/command.ts':
    "import { defineCommand } from 'citty';\n\nimport { greeting } from './greeting.ts';\n\nexport default defineCommand({\n  meta: {\n    name: 'hello',\n    description: 'Greet someone, or the world',\n  },\n  args: {\n    who: {\n      type: 'positional',\n      description: 'Who to greet',\n      required: false,\n    },\n  },\n  run({ args }) {\n    console.log(greeting(args.who));\n  },\n});\n",
  'files/source/commands/hello/greeting.property.test.ts':
    "import fc from 'fast-check';\nimport { describe, expect, it } from 'vitest';\n\nimport { greeting } from './greeting.ts';\n\ndescribe('greeting, over arbitrary names', () => {\n  it('always opens with the same word, whoever is named', () => {\n    fc.assert(\n      fc.property(fc.string(), (who) => {\n        expect(greeting(who).startsWith('hello ')).toBe(true);\n      }),\n    );\n  });\n\n  it('names whoever is given, whatever they are called', () => {\n    fc.assert(\n      fc.property(\n        fc.string().filter((who) => who !== ''),\n        (who) => {\n          expect(greeting(who)).toBe(`hello ${who}`);\n        },\n      ),\n    );\n  });\n});\n",
  'files/source/commands/hello/greeting.test.ts':
    "import { describe, expect, it } from 'vitest';\n\nimport { greeting } from './greeting.ts';\n\ndescribe('greeting from the command line', () => {\n  it('greets the world when no one is named', () => {\n    expect(greeting(undefined)).toBe('hello world');\n  });\n\n  it('greets the world when the name is left blank', () => {\n    expect(greeting('')).toBe('hello world');\n  });\n\n  it('greets whoever is named', () => {\n    expect(greeting('ada')).toBe('hello ada');\n  });\n});\n",
  'files/source/commands/hello/greeting.ts':
    "const EVERYONE = 'world';\n\nexport function greeting(who: string | undefined): string {\n  return `hello ${who === undefined || who === '' ? EVERYONE : who}`;\n}\n",
  'files/source/main.ts':
    "import { defineCommand } from 'citty';\n\nexport const main = defineCommand({\n  meta: {\n    name: '__PROJECT_NAME__',\n    description: 'A command line application under ket',\n  },\n  subCommands: {\n    hello: async () => (await import('./commands/hello/command.ts')).default,\n  },\n});\n",
  'files/source/run.ts':
    "import { runMain } from 'citty';\n\nimport { main } from './main.ts';\n\nawait runMain(main);\n",
